import os
from google import genai

client = genai.Client(api_key=os.environ["GEMINI_API_KEY"])

def build_cache_friendly_prompt(repo_tree: str, db_schema: str, recent_diff: str, user_task: str) -> list[str]:
    """Nguyen tac bat di bat dich: Bat bien (>4096 tok) o tren cung, Dong o duoi cung."""
    layer_1_immutable = f"[SCHEMA & AGENTS.md - STATIC]\n{db_schema}\n{repo_tree}"
    layer_2_semi_static = f"[RECENT GIT DIFF]\n{recent_diff}"
    layer_3_dynamic = f"[USER REQUEST]\n{user_task}"
    return [layer_1_immutable, layer_2_semi_static, layer_3_dynamic]

def run_argon_cached_session(static_bundle: str, task: str, prev_id: str | None = None):
    # Argon KHONG ho tro cachedContents.create; chi can giu prefix >= 4.096 tok giong het nhau
    kwargs = {
        "model": "gemini-4-argon",
        "store": True,
        "config": {"thinking_level": "medium", "max_output_tokens": 32768},
    }
    if prev_id:
        # Tiet kiem toi da: chi gui delta task moi, noi tiep state tren server (luu 55 ngay)
        return client.interactions.create(previous_interaction_id=prev_id, input=task, **kwargs)
    return client.interactions.create(input=f"{static_bundle}\n\n{task}", **kwargs)

# === Mau cau hinh Claude Prompt Cache TTL 1 gio (tranh bat /fast giua phien!) ===
CLAUDE_SYSTEM_BLOCK = [
    {
        "type": "text",
        "text": "<300K_STATIC_MONOREPO_SCHEMA_AND_RULES>",
        "cache_control": {"type": "ephemeral", "ttl": "1h"},  # 2x write, $0.20/1M read (Opus/Fable)
    }
]

def check_openai_272k_cliff(input_tokens: int) -> str:
    if input_tokens > 272000:
        return "WARNING: Vuot 272K! GPT-5.6 se nhan 2x Input/Cache & 1.5x Output. Hay compact xuong <260K hoac chuyen sang Argon/Sonnet."
    return "OK: Nam trong vung gia chuan (<=272K)."
